#!/usr/bin/env bash
# unityHPC/job_template.sh (llms-agents) — generated by /unity-hpc:connect. Do not hand-edit.
# run.sh cats this file under the #SBATCH header. It selects the stage body.
# UNITY_SCAFFOLD_VERSION=@@UNITY_HPC_VERSION@@
set -euo pipefail

REMOTE_DIR="${REMOTE_DIR/#\~/$HOME}"
APP="${REMOTE_DIR}/unityHPC"
export RESULTS_DIR="${REMOTE_RESULTS_DIR:-${REMOTE_DIR}/_results}/${CAMPAIGN}"

case "${LLMS_JOB:-train}" in
    eval)
        . "${APP}/eval_job.sh"
        ;;
    command)
        cd "$REMOTE_DIR"
        export PYTHONUNBUFFERED=1
        set +u
        [[ -f /usr/share/lmod/lmod/init/bash ]] && . /usr/share/lmod/lmod/init/bash
        set -u
        if [ -n "${MODULES:-}" ]; then
            module purge && module load ${MODULES}
        fi
        if [ -f "unityHPC/bootstrap.sh" ]; then
            exec 9>"${REMOTE_DIR}/.unity_bootstrap.lock"
            flock 9
            if [ -f "unityHPC/bootstrap.sh" ]; then
                . "unityHPC/bootstrap.sh"
            fi
            flock -u 9
            exec 9>&-
        else
            if [ -n "${VENV_PATH:-}" ] && [ -f "${VENV_PATH}/bin/activate" ]; then
                . "${VENV_PATH}/bin/activate"
            fi
        fi
        export LLMS_OUTPUT_DIR="${LLMS_OUTPUT_DIR:-${RESULTS_DIR}/${LLMS_STAGE_ID:-stage}}"
        export LLMS_PARENT_DIR="${LLMS_PARENT_DIR:-}"
        export LLMS_CHECKPOINT_DIR="${LLMS_CHECKPOINT_DIR:-${RESULTS_DIR}/checkpoint-final}"
        cmd="$JOB_COMMAND"
        cmd="${cmd//\{output_dir\}/$LLMS_OUTPUT_DIR}"
        cmd="${cmd//\{parent_dir\}/$LLMS_PARENT_DIR}"
        cmd="${cmd//\{checkpoint_dir\}/$LLMS_CHECKPOINT_DIR}"
        eval "$cmd"
        python3 "$APP/workflow.py" write-metrics \
            --results "$LLMS_OUTPUT_DIR" \
            --keys "${LLMS_METRIC_KEYS:-accuracy}" || true
        ;;
    *)
        . "${APP}/train_job.sh"
        ;;
esac
